function reset(atBoss=false){resetSoundPlayback();$('arcade-results').style.display='none';$('arcade-results').src='about:blank';voiceEpoch++;voicePending=null;voiceRemaining=0;for(const name of ['charVoice','amuroVoice'])for(const media of sfxPool[name]||[])media.pause();charZaku=null;charTrail=[];charAppeared=atBoss;optionClocks=[0,0,0,0];unlockSfx();stopBgm();seDuck=0;bgm.volume=.65;bgmBlocked=false;bgm.currentTime=0;time=atBoss?90:0;scroll=atBoss?9900:0;score=0;lives=3;selection=-1;wrecks=[];blastRings=[];afterimages=[];trailClock=0;shots=[];enemies=[];bullets=[];capsules=[];particles=[];history=[];wave=0;turret=0;eruption=0;fireClock=0;missileClock=0;shake=0;boss=null;player={x:160,y:H/2,inv:3,dying:0,backBoost:0,speed:0,missile:false,double:false,laser:false,options:0,evolved:false,shield:0,rapid:true,melee:null,meleeCooldown:0};launchBackdropOffset=0;launchBackdropSpeed=0;launch=atBoss?null:{age:0,kind:groundStage?'truck':'catapult'};if(launch)player.x=80;history=[{x:player.x,y:player.y}];if(atBoss){player.laser=true;player.options=1;player.shield=3;player.rapid=true}state='playing';$('overlay').style.display='none';keys.clear();releaseTouch();tone(650,.2);if(!atBoss&&!muted)playSfx('amuroVoice');updateBgm(0);hud();}
function showArcadeResults(newRecord){const media=$('arcade-results');const seconds=Math.floor(time),elapsed=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');media.src='arcade-results.html?stage='+stageNumber+'&bonus='+(groundStage?2000:5000)+'&score='+score+'&time='+elapsed+'&record='+(newRecord?'1':'0');media.style.display='block';}
window.addEventListener('message',event=>{const panel=$('arcade-results');if(event.origin===location.origin&&event.source===panel.contentWindow&&event.data?.type==='gundam-results-restart'&&(state==='clear'||state==='paused'&&pausedFrom==='clear')){if(stageNumber===1)nextStage();else reset();}});
function nextStage(){if((state!=='clear'&&!(state==='paused'&&pausedFrom==='clear'))||stageNumber!==1)return;const equipment={speed:player.speed,missile:player.missile,double:player.double,laser:player.laser,options:player.options,evolved:player.evolved,shield:player.shield,rapid:player.rapid},previousScore=score,previousLives=lives;stageNumber=2;groundStage=null;images.battlefield=images.spaceBattlefield;reset();Object.assign(player,equipment);score=previousScore;lives=previousLives;hud();}
function overlay(title,message,button){$('title').textContent=title;$('message').textContent=message;$('start').innerHTML=button+' <span>ENTER ↵</span>';$('overlay').style.display='flex';$('eyebrow').textContent=state==='paused'?'SIMULATION PAUSED':(groundStage?'STAGE 01 / GROUND FRONT':'STAGE 02 / COLONY GRAVEYARD');}
