function equipmentMax(i){if(!player)return false;return [player.speed>=4,player.missile,player.double,player.laser,player.options>=4,player.shield>=3,player.rapid,player.evolved][i];}
function equipmentAvailable(i){return i>=0&&i<names.length&&(i!==7||player?.options===4);}
function nextEquipment(){for(let count=0;count<names.length;count++){selection=(selection+1)%names.length;if(!equipmentMax(selection)&&equipmentAvailable(selection))return;}selection=-1;}
function upgrade(){if(state!=='playing'||selection<0||equipmentMax(selection)||!equipmentAvailable(selection))return;switch(selection){case 0:player.speed=Math.min(4,player.speed+1);break;case 1:player.missile=true;player.laser=false;break;case 2:player.double=true;player.laser=false;break;case 3:player.laser=true;player.missile=false;player.double=false;break;case 4:player.options=Math.min(4,player.options+1);break;case 5:player.shield=3;break;case 6:player.rapid=true;break;case 7:player.evolved=true;optionClocks=[0,0,0,0];break;}selection=-1;if(!muted&&!playSfx('equip'))tone(1100,.16,'triangle');hud();}
function explode(x,y,color='#ffaa64',n=18,sound='explosion'){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-180,180),vy:rand(-180,180),life:rand(.25,.7),color,r:rand(2,6)});shake=Math.max(shake,5);if(sound==='zaku'||sound==='suit')zakuDestroySound();else if(sound==='ship'){if(!muted){duckBgm(1.6);if(!playSfx('ship'))explosionSound(true)}}else if(sound!=='silent')explosionSound(n>=60);}
function destroySuit(suit,x,y,color='#ffaa64',duration=.48){const height=65*images.zaku.sh/images.zaku.sw;wrecks.push({suit,x,y,height,age:0,duration,burst:false,seed:rand(0,1000)});zakuDestroySound();duckBgm(1);}
function updateWrecks(dt){for(const w of wrecks){w.age+=dt;if(!w.burst&&w.age>=w.duration){w.burst=true;explode(w.x,w.y,'#ffaf63',26,'silent')}}wrecks=wrecks.filter(w=>w.age<w.duration+.65);}
function hit(){if(player.dying>0||player.inv>0||$('training').checked)return;if(player.shield>0){player.shield--;player.inv=1;explode(player.x,player.y,'#78efff',10);return}destroySuit(player.backBoost>0?'gundamBack':'gundam',player.x,player.y);lives--;player.dying=.48;player.inv=3;releaseTouch();keys.clear();hud();}
function sparkPaths(seed,tick,height){let value=(Math.floor(seed*10000)^Math.imul(tick+1,2654435761))>>>0;const random=()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296};const paths=[];if(random()<.16)return paths;const count=1+Math.floor(random()*3);for(let i=0;i<count;i++){let x=(random()-.5)*height*.95,y=(random()-.5)*height*.75;const points=[[x,y]],angle=random()*Math.PI*2,length=height*(.22+random()*.65),steps=3+Math.floor(random()*4);for(let k=1;k<=steps;k++){const jitter=(random()-.5)*height*.25;x+=Math.cos(angle)*length/steps-Math.sin(angle)*jitter;y+=Math.sin(angle)*length/steps+Math.cos(angle)*jitter;points.push([x,y])}paths.push(points);if(random()<.45){const origin=points[1+Math.floor(random()*(points.length-2))],branch=[origin];let bx=origin[0],by=origin[1];const direction=angle+(random()<.5?-1:1)*(.6+random());for(let k=0;k<2+Math.floor(random()*2);k++){bx+=Math.cos(direction)*height*.13+(random()-.5)*height*.14;by+=Math.sin(direction)*height*.13+(random()-.5)*height*.14;branch.push([bx,by])}paths.push(branch)}}return paths;}
function drawWrecks(){for(const w of wrecks){if(w.burst)continue;const im=images[w.suit];sprite(w.suit,w.x+Math.sin(w.age*95)*1.2,w.y,w.height*im.sw/im.sh,.9);const tick=Math.floor(w.age*26);ctx.save();ctx.translate(w.x,w.y);ctx.lineJoin='miter';ctx.lineCap='round';for(const points of sparkPaths(w.seed,tick,w.height)){ctx.beginPath();ctx.moveTo(...points[0]);for(const p of points.slice(1))ctx.lineTo(...p);ctx.shadowColor='#46dcff';ctx.shadowBlur=5;ctx.strokeStyle='#69d9ff';ctx.lineWidth=1.1;ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#edffff';ctx.lineWidth=.45;ctx.stroke()}ctx.restore();}}
