function moveZakuBoss(e,dt){const oldX=e.x;e.moveClock=(e.moveClock||0)-dt;if(e.goalX===undefined||e.moveClock<=0||Math.hypot(e.goalX-e.x,e.goalY-e.y)<15){e.goalX=rand(140,W-110);e.goalY=rand(85,terrainFloor()-70);e.moveClock=rand(1.2,2.3);}const dx=e.goalX-e.x,dy=e.goalY-e.y,distance=Math.hypot(dx,dy),step=Math.min(distance,(e.chief?300:250)*dt);if(distance>0){e.x+=dx/distance*step;e.y+=dy/distance*step;}if(e.x>oldX+.01)e.retreat=.08;e.shielding=!!e.chief&&e.age%4.4<2.8;}
function spawnWave(){const group=wave++,base=rand(150,520),red=group%3===0;if(groundStage&&time>=24){if(time>=80)return;const pursuit=time>=56&&group%2===0;for(let i=0;i<2;i++){const x=pursuit?-60-i*35:950+i*150,y=pursuit?clamp(player.y+(i?100:-100),100,terrainFloor()-65):terrain(scroll+x)-55;enemies.push({x,y,base:y,age:0,hp:2,type:'zaku',red:group%3===0&&i===1,phase:i,shot:7,size:65,canRetreat:false,independent:false,retreat:0,nextRetreat:999,ambush:!pursuit,pursuit,thrower:time>=56&&!pursuit&&i===1});}return;}for(let i=0;i<(groundStage?3:5);i++)enemies.push({x:W+55+i*80,y:base,base,age:-i*.3,hp:2,type:'zaku',red:red&&i===4,phase:group%3,shot:rand(6,7.5),size:65,canRetreat:Math.random()<.35,independent:false,soloGoal:0,soloClock:0,retreat:0,nextRetreat:rand(1.5,3.5)});}
const guardFormations=[{name:'横一列',points:[[-60,-100],[0,-100],[60,-100],[120,-100]]},{name:'四角',points:[[80,-135],[140,-135],[80,-65],[140,-65]]},{name:'ひし形',points:[[80,-165],[20,-105],[140,-105],[80,-45]]}];
function createGuardFormation(index=Math.floor(Math.random()*guardFormations.length)){const f=guardFormations[index];return {formation:f.name,guards:f.points.map(([x,y],i)=>({x,y,hp:3,max:3,shot:2+i*.65,flash:0}))};}
function guardPosition(g){return {x:boss.x+g.x,y:boss.y+g.y};}
function meleePosition(m){return m.kind==='guard'?guardPosition(m.target):m.target;}
function meleeContactSafe(target){return player.melee?.target===target&&player.melee.age<.42;}
function startMelee(){if(player.dying>0||player.melee||player.meleeCooldown>0)return false;const candidates=[];if(boss&&!boss.dying&&boss.x<=900)for(const g of boss.guards||[])if(g.hp>0)candidates.push({kind:'guard',target:g});for(const e of enemies)if(e.hp>0)candidates.push({kind:'enemy',target:e});if(charZaku&&charZaku.hp>0&&charZaku.mode!=='retreat')candidates.push({kind:'char',target:charZaku});const close=candidates.filter(m=>{const p=meleePosition(m);return p.x-player.x>=-10&&p.x-player.x<=95&&Math.abs(p.y-player.y)<=48;}).sort((a,b)=>{const p=meleePosition(a),q=meleePosition(b);return Math.hypot(p.x-player.x,p.y-player.y)-Math.hypot(q.x-player.x,q.y-player.y)});if(!close.length)return false;player.melee={...close[0],age:0,hit:false};player.meleeCooldown=.65;return true;}
function enemyDropsItem(e){if(e.red)return !boss||Math.random()<.25;return e.type==='turret'&&Math.random()<(boss?.1:.4);}
function dropBossItem(x,y){if(Math.random()<.5)capsules.push({x,y,age:0});}
function meleeStrike(m){const p=meleePosition(m);if(m.target.hp<=0||p.x-player.x< -20||p.x-player.x>110||Math.abs(p.y-player.y)>60)return;tone(900,.09,'triangle',.04);if(m.kind==='char'){hitChar({x:p.x,y:p.y,w:1,h:1,damage:3,life:1});return}m.target.hp=Math.max(0,m.target.hp-3);if(m.target.hp>0)return;if(m.kind==='guard'){score+=300;destroySuit('zakuShield',p.x,p.y);}else{const e=m.target;score+=e.type==='turret'?200:100;if(e.type==='zaku')destroySuit(e.retreat>0?'zakuBack':'zaku',e.x,e.y);else explode(e.x,e.y,'#a6efbe');if(enemyDropsItem(e))capsules.push({x:e.x,y:e.y,age:0});}}
function updateMelee(dt){player.meleeCooldown=Math.max(0,(player.meleeCooldown||0)-dt);if(player.dying>0){player.melee=null;return}if(player.melee){const m=player.melee;m.age+=dt;if(!m.hit&&m.age>=.12){m.hit=true;meleeStrike(m)}if(m.age>=.42)player.melee=null;}else startMelee();}
