function drawTerrain(top){const floor=terrainFloor();if(groundStage){groundStage.terrain(ctx,W,floor,scroll,top);return;}ctx.beginPath();ctx.moveTo(0,top?0:floor);for(let x=0;x<=W;x+=8)ctx.lineTo(x,terrain(scroll+x,top));ctx.lineTo(W,top?0:floor);ctx.closePath();const g=ctx.createLinearGradient(0,top?0:floor,0,top?180:floor-180);g.addColorStop(0,'#0c1725');g.addColorStop(.65,'#243545');g.addColorStop(1,'#4d6676');ctx.fillStyle=g;ctx.fill();ctx.strokeStyle='#819aaa';ctx.lineWidth=2;ctx.stroke();ctx.save();ctx.clip();for(let i=-1;i<22;i++){const x=i*70-scroll%70;ctx.fillStyle=i%3===0?'#2b414f':'#1a2b3a';ctx.fillRect(x,top?0:floor-260,64,260);ctx.strokeStyle='#526673';ctx.lineWidth=1;for(let j=0;j<4;j++){const y=top?j*52:floor-j*52;ctx.strokeRect(x+5,y-25,54,43);ctx.fillStyle='#0a1722';ctx.fillRect(x+10,y-19,4,4);ctx.fillRect(x+50,y+10,4,4)}ctx.strokeStyle='#7992a166';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,top?0:floor);ctx.lineTo(x+70,top?220:floor-220);ctx.moveTo(x+70,top?0:floor);ctx.lineTo(x,top?220:floor-220);ctx.stroke();if(i%4===0){ctx.fillStyle='#d6af42';for(let k=0;k<3;k++)ctx.fillRect(x+18+k*10,top?66:floor-70,5,4)}}ctx.restore();}
function musaiHull(x,y,pad=0){if(!boss)return false;const dx=x-boss.x,dy=y-boss.y;return dx>-300-pad&&dx<285+pad&&dy>20-pad&&dy<88+pad||dx>65-pad&&dx<285+pad&&dy>-43-pad&&dy<50+pad;}
function hitMusai(s){if(boss.dying||boss.x>900)return;const b=boss,overlap=(x,y,w,h)=>Math.abs(s.x-(b.x+x))<s.w/2+w/2&&Math.abs(s.y-(b.y+y))<s.h/2+h/2;const shield=(b.guards||[]).find(g=>g.hp>0&&overlap(g.x,g.y,56,64));if(shield){s.life=0;shield.flash=.12;return}const turret=b.turrets.find(t=>t.hp>0&&overlap(t.x,t.y-8,50,30));if(turret){s.life=0;turret.hp=Math.max(0,turret.hp-s.damage);if(turret.hp===0){score+=400;explode(b.x+turret.x,b.y+turret.y,'#ffb665',28);dropBossItem(b.x+turret.x,b.y+turret.y)}return}if(overlap(225,-78,66,94)){s.life=0;if((b.guards||[]).some(g=>g.hp>0))return;b.hp-=s.damage;particles.push({x:b.x+195,y:s.y,vx:-70,vy:0,life:.2,color:'#fff0a0',r:5});if(b.hp<=0)beginVictory();return}if(musaiHull(s.x,s.y,s.h/2))s.life=0;}
